<!doctype html><html lang="es"><head><meta charset="utf-8"><title>Saldos de bancos</title><?php include_once 'linker.php'; ?>
<style>.bank-control{padding:24px;color:#173e52}.control-hero{background:linear-gradient(110deg,#12384d,#0b656c);color:white;padding:28px;border-radius:18px}.control-panel{background:white;border:1px solid #cfe2ec;border-radius:16px;padding:22px;margin-top:20px}.control-cards{display:flex;flex-wrap:wrap;gap:16px}.control-card{flex:1;min-width:280px;border:1px solid #d4e4eb;border-top:5px solid #0b8c8d;border-radius:14px;padding:22px;margin:10px 0}.control-card strong{display:block;font-size:30px;margin:12px 0;color:#08776e}.control-form{display:flex;flex-wrap:wrap;gap:18px}.control-form label{flex:1;min-width:230px}.control-note{background:#eaf5f8;padding:16px;border-radius:10px;margin:16px 0}.control-scroll{overflow:auto}.bank-control table{width:100%;border-collapse:collapse}.bank-control td,.bank-control th{padding:12px;border-bottom:1px solid #dce8ee}.bank-control th{background:#153f54;color:white}.negative{color:#b22941!important}.control-error{color:#b22941;padding:12px}.control-actions{display:flex;gap:10px;flex-wrap:wrap}#control-success{color:#08776e;padding:12px}</style></head><body><?php include 'header.php'; ?>
<main class="bank-control"><section class="control-hero"><small>SOLO SUPERADMIN</small><h2>Saldos y control de cuentas bancarias</h2><p>Saldo inicial + ingresos − salidas = saldo de cada cuenta.</p><a class="btn btn-light" href="ReporteBancos.php">Ver reporte y generar PDF</a></section>
<div id="control-error" class="control-error" role="alert"></div><div id="control-success" role="status"></div>
<section class="control-panel"><h3>Saldo de cada banco al <span id="control-date"></span></h3><div id="control-cards" class="control-cards">Cargando cuentas...</div><p>Las cuentas sin saldo inicial muestran únicamente el neto de sus movimientos registrados.</p></section>
<section id="control-editor" class="control-panel" hidden><h3 id="control-title">Configurar saldo inicial</h3><p class="control-note">El saldo inicial es el dinero que tenía esta cuenta al comenzar la fecha indicada, antes de los movimientos de ese día. Desde esa fecha se suman ingresos y se restan salidas. Los movimientos anteriores se conservan, pero quedan fuera del nuevo control. No registres aquí un depósito o un pago: estos se ingresan en Caja y Banco.</p>
<form id="control-form"><div class="control-form"><label>Cuenta<input id="control-account" class="form-control" readonly></label><label>Fecha de inicio de control<input id="control-start" class="form-control" type="date" max="<?=$today?>" required></label><label>Saldo inicial (S/)<input id="control-amount" class="form-control" type="number" step=".01" min="-99999999" max="99999999" required></label></div><label style="display:block;margin:18px 0">Motivo / referencia del saldo<input id="control-reason" class="form-control" minlength="5" maxlength="500" required placeholder="Ejemplo: saldo del estado de cuenta al iniciar el control"></label><div class="control-actions"><button id="control-save" class="btn btn-success" type="submit">Guardar saldo inicial</button><button id="control-cancel" class="btn btn-secondary" type="button">Cerrar</button></div><div id="control-form-error" class="control-error" role="alert"></div></form></section>
<section id="control-history" class="control-panel" hidden><h3 id="control-history-title">Historial de cambios</h3><div id="control-history-data" class="control-scroll"></div></section></main>
<script>
(function(){const $=id=>document.getElementById(id),esc=v=>String(v==null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=v=>Number(v||0).toLocaleString('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2});let state=null,editing=null,saving=false;
 async function api(path,options){const r=await fetch('/api/index.php/bancos/'+path,Object.assign({credentials:'same-origin'},options)),d=await r.json();if(!r.ok)throw new Error(d.error||'No se pudo completar la operación');return d;}
 async function load(){try{state=await api('saldos');$('control-date').textContent=state.Fecha;let total=0;$('control-cards').innerHTML=state.Cuentas.map(c=>{total+=Number(c.SaldoActual);return '<article class="control-card"><h3>'+esc(c.Cuenta)+'</h3><small>Saldo registrado al '+esc(state.Fecha)+'</small><strong class="'+(Number(c.SaldoActual)<0?'negative':'')+'">S/ '+money(c.SaldoActual)+'</strong><p>'+(Number(c.Version)?'Saldo inicial: S/ '+money(c.SaldoInicial)+'<br>Control desde: '+esc(c.FechaInicio)+'<br>Registrado por: '+esc(c.UsuarioReg)+(c.UsuarioMod?'<br>Editado por: '+esc(c.UsuarioMod):''):'Sin saldo inicial configurado')+'</p><div class="control-actions">'+(!Number(c.Anulado)?'<button class="btn btn-info" data-edit="'+Number(c.IdCuenta)+'">'+(Number(c.Version)?'Editar saldo inicial':'Configurar saldo inicial')+'</button>':'Cuenta inactiva')+'<button class="btn btn-outline-info" data-history="'+Number(c.IdCuenta)+'">Ver cambios</button></div></article>';}).join('')+'<article class="control-card"><h3>Total bancos</h3><strong class="'+(total<0?'negative':'')+'">S/ '+money(total)+'</strong><p>Suma de los saldos registrados de todas las cuentas bancarias. Caja Principal excluida.</p></article>';}catch(e){$('control-error').textContent=e.message;$('control-cards').textContent='No se pudieron cargar las cuentas.';}}
 function edit(id){if(saving)return;editing=state.Cuentas.find(c=>Number(c.IdCuenta)===id);if(!editing)return;$('control-title').textContent=(Number(editing.Version)?'Editar saldo inicial — ':'Iniciar control — ')+editing.Cuenta;$('control-account').value=editing.Cuenta;$('control-start').value=editing.FechaInicio||state.Fecha;$('control-amount').value=editing.SaldoInicial===null?'':editing.SaldoInicial;$('control-reason').value='';$('control-form-error').textContent='';$('control-editor').hidden=false;$('control-editor').scrollIntoView({behavior:'smooth',block:'center'});}
 async function history(id){try{const c=state.Cuentas.find(c=>Number(c.IdCuenta)===id),rows=await api('saldos/historial?cuenta='+id);$('control-history-title').textContent='Cambios de saldo inicial — '+c.Cuenta;$('control-history-data').innerHTML=rows.length?'<table><thead><tr><th>Fecha</th><th>Usuario</th><th>Antes</th><th>Después</th><th>Motivo</th><th>Versión</th></tr></thead><tbody>'+rows.map(x=>{const before=x.DatosAntes?JSON.parse(x.DatosAntes):null,after=JSON.parse(x.DatosDespues);return '<tr><td>'+esc(x.Fecha)+'</td><td>'+esc(x.Usuario)+'</td><td>'+(before?'S/ '+money(before.SaldoInicial)+' · '+esc(before.FechaInicio):'Sin configuración')+'</td><td>S/ '+money(after.SaldoInicial)+' · '+esc(after.FechaInicio)+'</td><td>'+esc(x.Motivo)+'</td><td>'+esc(x.Version)+'</td></tr>';}).join('')+'</tbody></table>':'Sin cambios registrados.';$('control-history').hidden=false;}catch(e){$('control-error').textContent=e.message;}}
 $('control-cards').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.edit)edit(Number(b.dataset.edit));if(b.dataset.history)history(Number(b.dataset.history));});$('control-cancel').addEventListener('click',()=>{if(!saving)$('control-editor').hidden=true;});
 $('control-form').addEventListener('submit',async e=>{e.preventDefault();if(saving||!editing)return;saving=true;$('control-save').disabled=true;$('control-form-error').textContent='';try{await api('saldos',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({_csrf:state.csrf,IdCuenta:editing.IdCuenta,Version:Number(editing.Version),FechaInicio:$('control-start').value,SaldoInicial:$('control-amount').value,Motivo:$('control-reason').value})});$('control-success').textContent='Saldo inicial guardado. Los saldos de la cuenta ya se recalcularon.';$('control-editor').hidden=true;await load();await history(Number(editing.IdCuenta));}catch(error){$('control-form-error').textContent=error.message;}finally{saving=false;$('control-save').disabled=false;}});load();})();
</script></body></html>
